<?php require_once __DIR__.'/core.php'; $companyId=hrCompanyId($hrDb); $today=date('Y-m-d'); $count=(int)($hrDb->query("SELECT COUNT(*) n FROM hr_employees WHERE company_id=$companyId AND status='Active'")->fetch_assoc()['n']??0); $present=(int)($hrDb->query("SELECT COUNT(*) n FROM hr_attendance WHERE company_id=$companyId AND attendance_date='$today' AND status IN ('Present','Late','Paid Leave','Work From Home')")->fetch_assoc()['n']??0); $pending=(int)($hrDb->query("SELECT COUNT(*) n FROM hr_leave_requests WHERE company_id=$companyId AND status='Pending'")->fetch_assoc()['n']??0); $run=(int)($hrDb->query("SELECT COUNT(*) n FROM hr_payroll_runs WHERE company_id=$companyId AND payroll_month='".date('Y-m')."'")->fetch_assoc()['n']??0); $aiInsights=hrAiInsights($hrDb,$companyId); hrPageStart('Overview'); ?>
<div class="page-head"><div><h2>Good morning, Arjun.</h2><p>Your people operations, organised across every company.</p></div><div class="form-actions"><a class="button secondary" href="employee_dashboard.php"><i data-lucide="layout-dashboard"></i>View dashboard</a><a class="button" href="employees.php#add"><i data-lucide="user-plus"></i>Add employee</a></div></div>
